// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 2 ** 100);
        Attacker a = new Attacker(c);
        vm.deal(address(a), amount);
        a.deposit(amount);
        assertEq(address(c).balance, amount);
        a.attack();
        // Rule: each credit unit is paid out exactly once even under reentrancy,
        // so the attacker ends with exactly its deposit and the contract is empty.
        assertTrue(address(a).balance == amount && address(c).balance == 0);
    }
}

contract Attacker {
    ReentrancyDAO c;
    bool reentered;
    constructor(ReentrancyDAO c_) { c = c_; }
    function deposit(uint256 amt) external payable {
        address(c).call{value: amt}(abi.encodeWithSignature("deposit()"));
    }
    function attack() external { c.withdrawAll(); }
    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdrawAll();
        }
    }
}
